+
+// Scratch-only controls: the writer stays open through each single read.
+#[test]
+fn timeout_stdout_reads_available_bytes_without_waiting_for_eof() {
+    let (reader, mut writer) = std::io::pipe().unwrap();
+    writer.write_all(b"old-updater\n").unwrap();
+    let started = Instant::now();
+    let (before, after, interval, read) = stdout_now(&reader, started).unwrap();
+    eprintln!("stdout control: before={before:?} after={after:?} read_at={interval:?} read={read:?}");
+    assert!(after.contains(rustix::fs::OFlags::NONBLOCK));
+    assert_eq!(read.unwrap(), b"old-updater\n");
+    assert!(started.elapsed() < Duration::from_secs(2));
+    drop(writer);
+}
+
+#[test]
+fn timeout_stdout_leaves_a_live_empty_pipe_without_waiting_for_eof() {
+    let (reader, writer) = std::io::pipe().unwrap();
+    let started = Instant::now();
+    let (before, after, interval, read) = stdout_now(&reader, started).unwrap();
+    eprintln!("stdout control: before={before:?} after={after:?} read_at={interval:?} read={read:?}");
+    assert!(after.contains(rustix::fs::OFlags::NONBLOCK));
+    assert_eq!(read.unwrap_err(), rustix::io::Errno::AGAIN);
+    assert!(started.elapsed() < Duration::from_secs(2));
+    drop(writer);
+}
